import{_ as t,o as r,c as a,a2 as s}from"./chunks/framework.C9_66ieh.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md","lastUpdated":1785285552000}'),o={name:"getting-started.md"};function n(i,e,d,l,c,h){return r(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>Get TrueDeck running, open a project, and launch your first coding agent.</p><h2 id="download-recommended" tabindex="-1">Download (recommended) <a class="header-anchor" href="#download-recommended" aria-label="Permalink to &quot;Download (recommended)&quot;">​</a></h2><p><strong>End users should not clone the repo.</strong> Install a prebuilt binary from GitHub Releases:</p><p><strong><a href="https://github.com/WutIsHummus/TrueDeck/releases" target="_blank" rel="noreferrer">https://github.com/WutIsHummus/TrueDeck/releases</a></strong></p><table tabindex="0"><thead><tr><th>Asset</th><th>Use</th></tr></thead><tbody><tr><td><strong>TrueDeck Setup … .exe</strong></td><td>Windows installer (recommended)</td></tr><tr><td><strong>TrueDeck … .exe</strong></td><td>Windows portable (no installer)</td></tr></tbody></table><p>Run the app, then install any coding CLIs you want on <code>PATH</code> (<code>grok</code>, <code>codex</code>, <code>claude</code>, <code>cursor-agent</code>, …).</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Notes</th></tr></thead><tbody><tr><td><strong>OS</strong></td><td>Windows x64 builds are published first; macOS / Linux when available</td></tr><tr><td><strong>Agent CLIs</strong></td><td>Install the CLIs you want on <code>PATH</code>: <code>grok</code>, <code>codex</code>, <code>claude</code>, <code>gemini</code>, <code>cursor-agent</code>, …</td></tr><tr><td><strong>Node.js 20+</strong></td><td>Only for <strong>building from source</strong> (contributors)</td></tr><tr><td><strong>Rust toolchain</strong> (contributors)</td><td>Required to build the main <code>truedeck-backend</code> binary from source</td></tr></tbody></table><blockquote><p>Tools like <strong>Rojo</strong> are not coding-agent CLIs. You can still run them as <strong>on-open project commands</strong> (Settings → Project) so they open as shell panes when you open that folder.</p></blockquote><h2 id="first-launch-from-a-release" tabindex="-1">First launch (from a release) <a class="header-anchor" href="#first-launch-from-a-release" aria-label="Permalink to &quot;First launch (from a release)&quot;">​</a></h2><ol><li>Install or run the <code>.exe</code> from Releases.</li><li>Open a project (<strong>Ctrl+O</strong> or the project menu).</li><li>Launch an agent (<strong>Ctrl+T</strong>).</li></ol><h2 id="develop-from-source-contributors" tabindex="-1">Develop from source (contributors) <a class="header-anchor" href="#develop-from-source-contributors" aria-label="Permalink to &quot;Develop from source (contributors)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/WutIsHummus/TrueDeck.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TrueDeck</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Command</th><th>What</th></tr></thead><tbody><tr><td><code>npm start</code></td><td>Studio UI (dev)</td></tr><tr><td><code>npm run tui</code></td><td>Terminal-only deck</td></tr><tr><td><code>npm run dist:win</code></td><td>Build Windows installer + portable</td></tr></tbody></table><p>See <a href="./development">Development</a> for packaging details. Runs the Blessed-based TUI (<code>tui/index.ts</code>) without Electron. Prefer Studio for pane groups, task board, and settings.</p><h2 id="first-run-onboarding" tabindex="-1">First-run onboarding <a class="header-anchor" href="#first-run-onboarding" aria-label="Permalink to &quot;First-run onboarding&quot;">​</a></h2><p>On a fresh profile TrueDeck walks you through:</p><ol><li><strong>Welcome</strong></li><li><strong>Preferred CLI</strong> - Cursor Agent, Claude, Codex, Grok, Gemini, Shell, …</li><li><strong>Memory space</strong> - default palace, detected folder, or browse an existing path</li><li><strong>Repo</strong> - pick a project folder</li><li><strong>Inject + launch</strong> - MCP / auto-context pointers + start your preferred agent</li></ol><p>Replay later: <strong>?</strong> in the title bar, or <strong>Settings → About → Replay onboarding</strong>.</p><p>Memory is automatic after this: TrueDeck writes <code>.truedeck/auto-context.md</code>, ensures <code>.memory/</code>, and injects env paths into agent processes. See <a href="./memory-providers">Memory providers</a>.</p><h2 id="first-project" tabindex="-1">First project <a class="header-anchor" href="#first-project" aria-label="Permalink to &quot;First project&quot;">​</a></h2><ol><li>Press <strong>Ctrl+O</strong> (or use <strong>Project ▾</strong> in the title bar).</li><li>Choose a folder. TrueDeck stores it under app data as a project with on-open commands and default agents.</li><li>The folder name appears in the project menu (VS Code-style chevron + recents).</li></ol><p>Project metadata lives in app data (<code>projects.json</code>), not only inside the repo. Per-repo agent context still uses <code>.memory/</code> and <code>.truedeck/</code> under the project root.</p><h2 id="first-agent" tabindex="-1">First agent <a class="header-anchor" href="#first-agent" aria-label="Permalink to &quot;First agent&quot;">​</a></h2><ol><li>Open a project (<strong>Ctrl+O</strong>).</li><li>Press <strong>Ctrl+T</strong> to open the agent palette.</li><li>Pick an agent (Grok, Codex, Claude, Cursor Agent, Shell, …).</li><li>A PTY session opens in the active pane group. TrueDeck:</li></ol><ul><li>Resolves the CLI binary (never Cursor IDE for the Cursor agent)</li><li>Injects memory env vars</li><li>Wraps the process in the <a href="./agent-frame">agent frame</a> when enabled</li></ul><p>If a CLI is missing, the palette / spawn error shows an install one-liner. Example for Cursor Agent on Windows:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">irm https:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">//</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cursor.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">install?win</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> iex</span></span></code></pre></div><h2 id="first-task" tabindex="-1">First task <a class="header-anchor" href="#first-task" aria-label="Permalink to &quot;First task&quot;">​</a></h2><ol><li>Press <strong>Ctrl+B</strong> to open the task board.</li><li>Create a task (title + details).</li><li>Assign an agent and <strong>Run</strong> / dispatch.</li><li>TrueDeck writes <code>.truedeck/tasks/&lt;id&gt;.md</code>, sets <code>TRUEDECK_TASK_*</code> env, spawns the agent, and seeds a short prompt into the PTY.</li></ol><p>Details: <a href="./task-board">Task board</a>.</p><h2 id="quick-command-reference" tabindex="-1">Quick command reference <a class="header-anchor" href="#quick-command-reference" aria-label="Permalink to &quot;Quick command reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What</th></tr></thead><tbody><tr><td><code>npm start</code></td><td>Studio UI (default)</td></tr><tr><td><code>npm run tui</code></td><td>Terminal-only deck</td></tr><tr><td><code>npm run build</code></td><td>Production compile (<code>out/</code>)</td></tr><tr><td><code>npm run dist:win</code></td><td>Windows installer (electron-builder)</td></tr><tr><td><code>npm run build:backend</code></td><td>Build main Rust backend (<code>truedeck-backend</code>)</td></tr><tr><td><code>npm run build:pty</code></td><td>Build legacy Rust PTY sidecar</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./user-guide">User guide</a> - panes, restore, settings</li><li><a href="./keyboard-shortcuts">Keyboard shortcuts</a></li><li><a href="./agents">Agents</a> - CLI resolve and Cursor policy</li><li><a href="./configuration">Configuration</a> - settings and env vars</li></ul>`,36)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
